 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Extend each colored vertical ray toward the 5 endpoint line.
    for c in range(w):
        if grid[h-1][c] == 5:
            color = None
            for r in range(h-1, -1, -1):
                if grid[r][c] == 5: color = 5
                elif grid[r][c] != 0: color = grid[r][c]
                elif color is not None: out[r][c] = color
    return out
